<template>
	<div>
		<el-dialog modal-class="edit_form_modal" class="edit_form" v-model="formVisible" :title="formTitle" width="80%" destroy-on-close :fullscreen='false'>
			<el-form class="formModel_form" ref="formRef" :model="form" :rules="rules">
				<el-row >
					<el-col :span="12">
						<el-form-item label="摄影账号" prop="sheyingzhanghao">
							<el-input class="list_inp" v-model="form.sheyingzhanghao" placeholder="摄影账号"
                                type="text"
								:readonly="!isAdd||disabledForm.sheyingzhanghao?true:false" />
						</el-form-item>
					</el-col>

					<el-col :span="12">
						<el-form-item label="摄影姓名" prop="sheyingxingming">
							<el-input class="list_inp" v-model="form.sheyingxingming" placeholder="摄影姓名"
                                type="text"
								:readonly="!isAdd||disabledForm.sheyingxingming?true:false" />
						</el-form-item>
					</el-col>

					<el-col :span="12">
						<el-form-item prop="sheyingshizhaopian"
									  label="摄影师照片"
						>
							<uploads
								:disabled="!isAdd||disabledForm.sheyingshizhaopian?true:false"
								action="file/upload"
								tip="请上传摄影师照片"
								style="width: 100%;text-align: left;"
								:fileUrls="form.sheyingshizhaopian?form.sheyingshizhaopian:''" 
								@change="sheyingshizhaopianUploadSuccess">
							</uploads>
						</el-form-item>
					</el-col>
					<el-col :span="12">
						<el-form-item label="分类" prop="fenlei">
							<el-select
								class="list_sel"
								:disabled="!isAdd||disabledForm.fenlei?true:false"
								v-model="form.fenlei" 
								placeholder="请选择分类"
								>
								<el-option v-for="(item,index) in fenleiLists" :label="item"
									:value="item"
									>
								</el-option>
							</el-select>
						</el-form-item>
					</el-col>
					<el-col :span="12">
						<el-form-item label="简介" prop="jianjie">
							<el-input class="list_inp" v-model="form.jianjie" placeholder="简介"
                                type="text"
								:readonly="!isAdd||disabledForm.jianjie?true:false" />
						</el-form-item>
					</el-col>

					<el-col :span="12">
						<el-form-item label="预约价格" prop="yuyuejiage">
							<el-input class="list_inp" v-model.number="form.yuyuejiage" placeholder="预约价格"
                                type="number"
                                @mousewheel.native.prevent
								:readonly="!isAdd||disabledForm.yuyuejiage?true:false" />
						</el-form-item>
					</el-col>

					<el-col :span="24">
						<el-form-item label="工作经历" prop="gongzuojingli">
							<el-input v-model="form.gongzuojingli" placeholder="工作经历" type="textarea"
							:readonly="!isAdd||disabledForm.gongzuojingli?true:false"
							/>
						</el-form-item>
					</el-col>
					<el-col :span="24">
						<el-form-item label="专业技能" prop="zhuanyejineng">
							<el-input v-model="form.zhuanyejineng" placeholder="专业技能" type="textarea"
							:readonly="!isAdd||disabledForm.zhuanyejineng?true:false"
							/>
						</el-form-item>
					</el-col>
					<el-col :span="24">
						<el-form-item label="个人特长" prop="gerentezhang">
							<el-input v-model="form.gerentezhang" placeholder="个人特长" type="textarea"
							:readonly="!isAdd||disabledForm.gerentezhang?true:false"
							/>
						</el-form-item>
					</el-col>
				</el-row>
			</el-form>
			<template #footer v-if="isAdd||type=='logistics'||type=='reply'">
				<span class="formModel_btn_box">
					<el-button class="cancel_btn" @click="closeClick">取消</el-button>
					<el-button class="confirm_btn" type="primary" @click="save"
						>
						提交
					</el-button>
				</span>
			</template>
		</el-dialog>
	</div>
</template>
<script setup>
	import {
		reactive,
		ref,
		getCurrentInstance,
		nextTick,
		computed,
		defineEmits
	} from 'vue'
    import {
        useStore
    } from 'vuex';
    const store = useStore()
    const user = computed(()=>store.getters['user/session'])
	const context = getCurrentInstance()?.appContext.config.globalProperties;	
	const emit = defineEmits(['formModelChange'])
	//基础信息
	const tableName = 'sheyingshixinxi'
	const formName = '摄影师信息'
	//基础信息
	//form表单
	const form = ref({})
	const disabledForm = ref({
        sheyingzhanghao : false,
        sheyingxingming : false,
        sheyingshizhaopian : false,
        fenlei : false,
        jianjie : false,
        yuyuejiage : false,
        gongzuojingli : false,
        zhuanyejineng : false,
        gerentezhang : false,
        sfsh : false,
        shhf : false,
        discussNumber : false,
	})
	const formVisible = ref(false)
	const isAdd = ref(false)
	const formTitle = ref('')
    
	const rules = ref({
		sheyingzhanghao: [
		],
		sheyingxingming: [
		],
		sheyingshizhaopian: [
		],
		fenlei: [
		],
		jianjie: [
		],
		yuyuejiage: [
			{ validator: context.$toolUtil.validator.number, trigger: 'blur' },
		],
		gongzuojingli: [
		],
		zhuanyejineng: [
		],
		gerentezhang: [
		],
		sfsh: [
		],
		shhf: [
		],
		discussNumber: [
			{ validator: context.$toolUtil.validator.intNumber, trigger: 'blur' },
		],
	})
	//表单验证
	
	const formRef = ref(null)
	const id = ref(0)
	const type = ref('')
	//摄影师照片上传回调
	const sheyingshizhaopianUploadSuccess=(e)=>{
		form.value.sheyingshizhaopian = e
	}
	//分类列表
	const fenleiLists = ref([])

	//获取唯一标识
	const getUUID =()=> {
      return new Date().getTime();
    }
	//重置
	const resetForm = () => {
		form.value = {
			sheyingzhanghao: '',
			sheyingxingming: '',
			sheyingshizhaopian: '',
			fenlei: '',
			jianjie: '',
			yuyuejiage: '',
			gongzuojingli: '',
			zhuanyejineng: '',
			gerentezhang: '',
			shhf: '',
		}
	}
	//获取info
	const getInfo = ()=>{
		context?.$http({
			url: `${tableName}/info/${id.value}`,
			method: 'get'
		}).then(res => {
			let reg=new RegExp('../../../file','g')
			form.value = res.data.data
			formVisible.value = true
		})
	}
	const crossRow = ref('')
	const crossTable = ref('')
	const crossTips = ref('')
	const crossColumnName = ref('')
	const crossColumnValue = ref('')
	//初始化
	const init=(formId=null,formType='add',formNames='',row=null,table=null,statusColumnName=null,tips=null,statusColumnValue=null)=>{
		resetForm()
		if(formId){
			id.value = formId
			type.value = formType
		}
		if(formType == 'add'){
			isAdd.value = true
			formTitle.value = '新增' + formName
			formVisible.value = true
		}else if(formType == 'info'){
			isAdd.value = false
			formTitle.value = '查看' + formName
			getInfo()
		}else if(formType == 'edit'){
			isAdd.value = true
			formTitle.value = '修改' + formName
			getInfo()
		}
		else if(formType == 'cross'){
			isAdd.value = true
			formTitle.value = formNames
			// getInfo()
			for(let x in row){
				if(x=='sheyingzhanghao'){
					form.value.sheyingzhanghao = row[x];
					disabledForm.value.sheyingzhanghao = true;
					continue;
				}
				if(x=='sheyingxingming'){
					form.value.sheyingxingming = row[x];
					disabledForm.value.sheyingxingming = true;
					continue;
				}
				if(x=='sheyingshizhaopian'){
					form.value.sheyingshizhaopian = row[x];
					disabledForm.value.sheyingshizhaopian = true;
					continue;
				}
				if(x=='fenlei'){
					form.value.fenlei = row[x];
					disabledForm.value.fenlei = true;
					continue;
				}
				if(x=='jianjie'){
					form.value.jianjie = row[x];
					disabledForm.value.jianjie = true;
					continue;
				}
				if(x=='yuyuejiage'){
					form.value.yuyuejiage = row[x];
					disabledForm.value.yuyuejiage = true;
					continue;
				}
				if(x=='gongzuojingli'){
					form.value.gongzuojingli = row[x];
					disabledForm.value.gongzuojingli = true;
					continue;
				}
				if(x=='zhuanyejineng'){
					form.value.zhuanyejineng = row[x];
					disabledForm.value.zhuanyejineng = true;
					continue;
				}
				if(x=='gerentezhang'){
					form.value.gerentezhang = row[x];
					disabledForm.value.gerentezhang = true;
					continue;
				}
				if(x=='discussNumber'){
					form.value.discussNumber = row[x];
					disabledForm.value.discussNumber = true;
					continue;
				}
			}
			if(row){
				crossRow.value = row
			}
			if(table){
				crossTable.value = table
			}
			if(tips){
				crossTips.value = tips
			}
			if(statusColumnName){
				crossColumnName.value = statusColumnName
			}
			if(statusColumnValue){
				crossColumnValue.value = statusColumnValue
			}
			formVisible.value = true
		}

		context?.$http({
			url: `${context?.$toolUtil.storageGet('sessionTable')}/session`,
			method: 'get'
		}).then(res => {
			var json = res.data.data
			if(json.hasOwnProperty('sheyingzhanghao')&& context?.$toolUtil.storageGet("role")!="管理员"){
				form.value.sheyingzhanghao = json.sheyingzhanghao
				disabledForm.value.sheyingzhanghao = true;
			}
			if(json.hasOwnProperty('sheyingxingming')&& context?.$toolUtil.storageGet("role")!="管理员"){
				form.value.sheyingxingming = json.sheyingxingming
				disabledForm.value.sheyingxingming = true;
			}
		})
		context?.$http({
			url: `option/fenlei/fenlei`,
			method: 'get'
		}).then(res=>{
			fenleiLists.value = res.data.data
		})
	}
	//初始化
	//声明父级调用
	defineExpose({
		init
	})
	//关闭
	const closeClick = () => {
		formVisible.value = false
	}
	//富文本
	const editorChange = (e,name) =>{
		form.value[name] = e
	}
	//提交
	const save= async ()=>{
		if(form.value.sheyingshizhaopian!=null) {
			form.value.sheyingshizhaopian = form.value.sheyingshizhaopian.replace(new RegExp(context?.$config.url,"g"),"");
		}
		var table = crossTable.value
		var objcross = JSON.parse(JSON.stringify(crossRow.value))
		let crossUserId = ''
		let crossRefId = ''
		let crossOptNum = ''
		if(type.value == 'cross'){
			if(crossColumnName.value!=''){
				if(!crossColumnName.value.startsWith('[')){
					for(let o in objcross){
						if(o == crossColumnName.value){
							objcross[o] = crossColumnValue.value
						}
					}
					//修改跨表数据
					changeCrossData(objcross)
				}else{
					crossUserId = user.value.id
					crossRefId = objcross['id']
					crossOptNum = crossColumnName.value.replace(/\[/,"").replace(/\]/,"")
				}
			}
		}
		formRef.value.validate((valid)=>{
			if(valid){
				if(crossUserId&&crossRefId){
					form.value.crossuserid = crossUserId
					form.value.crossrefid = crossRefId
					let params = {
						page: 1,
						limit: 1000, 
						crossuserid:form.value.crossuserid,
						crossrefid:form.value.crossrefid,
					}
					context?.$http({
						url: `${tableName}/page`,
						method: 'get', 
						params: params 
					}).then(res=>{
						if(res.data.data.total>=crossOptNum){
							context?.$toolUtil.message(`${crossTips.value}`,'error')
							return false
						}else{
							context?.$http({
								url: `${tableName}/${!form.value.id ? "save" : "update"}`,
								method: 'post', 
								data: form.value 
							}).then(async res=>{
								emit('formModelChange')
								context?.$toolUtil.message(`操作成功`,'success')
                                formVisible.value = false
							})
						}
					})
				}else{
					context?.$http({
						url: `${tableName}/${!form.value.id ? "save" : "update"}`,
						method: 'post', 
						data: form.value 
					}).then(async (res)=>{
						emit('formModelChange')
						context?.$toolUtil.message(`操作成功`,'success')
                        formVisible.value = false
					})
				}
			}else{
                context.$message.error('请完善信息')
            }
		})
	}
	//修改跨表数据
	const changeCrossData = async (row)=>{
        if(type.value == 'cross'){
            await context?.$http({
                url: `${crossTable.value}/update`,
                method: 'post',
                data: row
            }).then(res=>{})
        }
	}
</script>
<style lang="scss" scoped>
	// 表单
	.formModel_form{
		// form item
		:deep(.el-form-item) {
			//label
			.el-form-item__label {
			}
			// 内容盒子
			.el-form-item__content {
				// 输入框
				.list_inp {
				}
				// 下拉框
				.list_sel {
					//去掉默认样式
					.select-trigger{
						height: 100%;
						.el-input{
							height: 100%;
						}
					}
				}
				// 长文本
				.el-textarea__inner {
				}
				//图片上传样式
				.el-upload-list  {
					//提示语
					.el-upload__tip {
					}
					//外部盒子
					.el-upload--picture-card {
						//图标
						.el-icon{
						}
					}
					.el-upload-list__item {
					}
				}
			}
		}
	}
	// 按钮盒子
	.formModel_btn_box {
		.cancel_btn {
		}
		.cancel_btn:hover {
		}
		
		.confirm_btn {
		}
		.confirm_btn:hover {
		}
	}
</style>
